import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_src = r"""
#include <torch/extension.h>

torch::Tensor cute_conv_transpose2d(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t padding_h,
    int64_t padding_w,
    int64_t dilation_h,
    int64_t dilation_w,
    int64_t groups);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <int TILE_H, int TILE_W, int TILE_OC>
__global__ void cute_conv_transpose2d_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N,
    int C_in,
    int H_in,
    int W_in,
    int C_out,
    int H_out,
    int W_out,
    int K_h,
    int K_w,
    int stride_h,
    int stride_w,
    int padding_h,
    int padding_w,
    int dilation_h,
    int dilation_w,
    int groups,
    int C_in_group,
    int C_out_group,
    int H_tiles)
{
    constexpr int TILE_PIXELS = TILE_H * TILE_W;
    constexpr int THREADS = TILE_PIXELS * TILE_OC;

    int tid = threadIdx.x;
    if (tid >= THREADS) {
        return;
    }

    int pixel = tid / TILE_OC;
    int oc_lane = tid % TILE_OC;

    int local_h = pixel / TILE_W;
    int local_w = pixel % TILE_W;

    int tile_x = blockIdx.x;
    int tile_y = blockIdx.y;

    int group_height_tile = tile_y % H_tiles;
    int batch_group = tile_y / H_tiles;

    int n = batch_group / groups;
    int group = batch_group % groups;

    int oh = group_height_tile * TILE_H + local_h;
    int ow = tile_x * TILE_W + local_w;

    int oc_tile = blockIdx.z;
    int oc_in_group = oc_tile * TILE_OC + oc_lane;
    int oc = group * C_out_group + oc_in_group;

    if (n >= N || oh >= H_out || ow >= W_out ||
        oc_in_group >= C_out_group) {
        return;
    }

    auto gX = make_tensor(
        make_gmem_ptr(x),
        make_shape(N, C_in, H_in, W_in),
        make_stride(C_in * H_in * W_in, H_in * W_in, W_in, 1));

    auto gW = make_tensor(
        make_gmem_ptr(weight),
        make_shape(C_in, C_out_group, K_h, K_w),
        make_stride(C_out_group * K_h * K_w, K_h * K_w, K_w, 1));

    auto gY = make_tensor(
        make_gmem_ptr(output),
        make_shape(N, C_out, H_out, W_out),
        make_stride(C_out * H_out * W_out, H_out * W_out, W_out, 1));

    float acc = bias != nullptr ? bias[oc] : 0.0f;

    for (int kh = 0; kh < K_h; ++kh) {
        int ih_numerator = oh + padding_h - kh * dilation_h;
        if (ih_numerator < 0 || ih_numerator % stride_h != 0) {
            continue;
        }

        int ih = ih_numerator / stride_h;
        if (ih < 0 || ih >= H_in) {
            continue;
        }

        for (int kw = 0; kw < K_w; ++kw) {
            int iw_numerator = ow + padding_w - kw * dilation_w;
            if (iw_numerator < 0 || iw_numerator % stride_w != 0) {
                continue;
            }

            int iw = iw_numerator / stride_w;
            if (iw < 0 || iw >= W_in) {
                continue;
            }

            for (int ic_group = 0; ic_group < C_in_group; ++ic_group) {
                int ic = group * C_in_group + ic_group;
                acc += gX(n, ic, ih, iw) *
                       gW(ic, oc_in_group, kh, kw);
            }
        }
    }

    gY(n, oc, oh, ow) = acc;
}

torch::Tensor cute_conv_transpose2d(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t padding_h,
    int64_t padding_w,
    int64_t dilation_h,
    int64_t dilation_w,
    int64_t groups)
{
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
     TORCH_CHECK(!bias.has_value() || bias->is_cuda(), "bias must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
     TORCH_CHECK(!bias.has_value() || bias->scalar_type() == at::kFloat,
                 "bias must be float32");
    TORCH_CHECK(x.dim() == 4, "x must be NCHW");
    TORCH_CHECK(weight.dim() == 4, "weight must be [Cin, Cout/groups, Kh, Kw]");
    TORCH_CHECK(groups > 0, "groups must be positive");
    TORCH_CHECK(x.size(1) % groups == 0, "input channels must be divisible by groups");
    TORCH_CHECK(weight.size(0) == x.size(1), "weight input channels mismatch");

    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    torch::Tensor b_c;
     if (bias.has_value()) {
         b_c = bias->contiguous();
     }

    int N = static_cast<int>(x_c.size(0));
    int C_in = static_cast<int>(x_c.size(1));
    int H_in = static_cast<int>(x_c.size(2));
    int W_in = static_cast<int>(x_c.size(3));

    int C_out_group = static_cast<int>(w_c.size(1));
    int K_h = static_cast<int>(w_c.size(2));
    int K_w = static_cast<int>(w_c.size(3));

    int groups_i = static_cast<int>(groups);
    int C_in_group = C_in / groups_i;
    int C_out = C_out_group * groups_i;

     TORCH_CHECK(!bias.has_value() || b_c.numel() == C_out,
                 "bias size mismatch");

    int H_out =
        (H_in - 1) * static_cast<int>(stride_h)
        - 2 * static_cast<int>(padding_h)
        + static_cast<int>(dilation_h) * (K_h - 1)
        + 1;

    int W_out =
        (W_in - 1) * static_cast<int>(stride_w)
        - 2 * static_cast<int>(padding_w)
        + static_cast<int>(dilation_w) * (K_w - 1)
        + 1;

    TORCH_CHECK(H_out >= 0 && W_out >= 0, "invalid output dimensions");

    auto output = torch::empty(
        {N, C_out, H_out, W_out},
        x_c.options());

    constexpr int TILE_H = 8;
    constexpr int TILE_W = 8;
    constexpr int TILE_OC = 4;

    int H_tiles = (H_out + TILE_H - 1) / TILE_H;
    int W_tiles = (W_out + TILE_W - 1) / TILE_W;
    int OC_tiles = (C_out_group + TILE_OC - 1) / TILE_OC;

    dim3 block(TILE_H * TILE_W * TILE_OC);
    dim3 grid(
        W_tiles,
        N * groups_i * H_tiles,
        OC_tiles);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_conv_transpose2d_kernel<TILE_H, TILE_W, TILE_OC>
        <<<grid, block, 0, stream>>>(
            x_c.data_ptr<float>(),
            w_c.data_ptr<float>(),
             bias.has_value() ? b_c.data_ptr<float>() : nullptr,
            output.data_ptr<float>(),
            N,
            C_in,
            H_in,
            W_in,
            C_out,
            H_out,
            W_out,
            K_h,
            K_w,
            static_cast<int>(stride_h),
            static_cast<int>(stride_w),
            static_cast<int>(padding_h),
            static_cast<int>(padding_w),
            static_cast<int>(dilation_h),
            static_cast<int>(dilation_w),
            groups_i,
            C_in_group,
            C_out_group,
            H_tiles);

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CUTE transposed convolution launch failed");

    return output;
}
"""


cute_ext = load_inline(
    name="cute_conv_transpose2d_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["cute_conv_transpose2d"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: tuple,
        stride: tuple = (1, 1),
        padding: tuple = (0, 0),
        dilation: tuple = (1, 1),
        groups: int = 1,
        bias: bool = False,
    ) -> None:
        super().__init__()

        self.conv_transpose2d = nn.ConvTranspose2d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            dilation=dilation,
            groups=groups,
            bias=bias,
        )
        self._ext = cute_ext
        self._stride = stride
        self._padding = padding
        self._dilation = dilation
        self._groups = groups

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        bias = self.conv_transpose2d.bias
        return self._ext.cute_conv_transpose2d(
            x,
            self.conv_transpose2d.weight,
            bias,
            int(self._stride[0]),
            int(self._stride[1]),
            int(self._padding[0]),
            int(self._padding[1]),
            int(self._dilation[0]),
            int(self._dilation[1]),
            int(self._groups),
        )

